CREATE TABLE IF NOT EXISTS heating_payment_requests (id TEXT PRIMARY KEY,apartment_id TEXT NOT NULL REFERENCES apartments(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),requested_on TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'unpaid' CHECK(status IN ('unpaid','pending','confirmed')),declared_on TEXT,confirmed_on TEXT,payment_id TEXT REFERENCES payments(id),created_by TEXT NOT NULL REFERENCES users(id),reviewed_by TEXT REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_heating_requests_apartment ON heating_payment_requests(apartment_id,created_at DESC);
